// Generated by scaffold-html-to-react-page (deterministic design transpile) from html/frontend/04-onboarding.html
// Structure + styling are faithful to the proto. DATA WIRING (fetch/list/handlers) is layered on after.
import { useState } from 'react';
import { useNavigate } from 'react-router';
import { ArrowLeft, Delete, Rocket, School } from 'lucide-react';
import { CoverFill } from '~/components/shared/CoverFill';
import { useScreenQuery } from '~/hooks/useScreenQuery';
import { useAppSelector } from '~/hooks/useAppSelector';
import { createStudent } from '~/services/httpServices/studentsService';
import '~/styles/protos/onboarding.css';

/** The keypad prints Bangla numerals; the API stores an ASCII PIN. */
const BANGLA_DIGITS: Record<string, string> = {
  '০': '0', '১': '1', '২': '2', '৩': '3', '৪': '4',
  '৫': '5', '৬': '6', '৭': '7', '৮': '8', '৯': '9',
};

export default function OnboardingPage() {
  const sessionUser = useAppSelector((s) => s.auth.user);
  const { data } = useScreenQuery("GET /api/onboarding");
  const navigate = useNavigate();
  const [name, setName] = useState('');
  const [classNo, setClassNo] = useState(4);
  const [avatar, setAvatar] = useState('owl');
  const [pin, setPin] = useState('');
  const [confirmPin, setConfirmPin] = useState('');
  const [activeField, setActiveField] = useState<'pin' | 'confirm'>('pin');
  const [pinError, setPinError] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const canSubmit =
    name.trim().length >= 2 &&
    name.trim().length <= 30 &&
    pin.length === 4 &&
    confirmPin.length === 4 &&
    pin === confirmPin &&
    !submitting;

  const pressDigit = (banglaDigit: string) => {
    if (submitting) return;
    const digit = BANGLA_DIGITS[banglaDigit] ?? banglaDigit;
    setSubmitError(null);
    if (activeField === 'pin') {
      if (pin.length >= 4) return;
      const next = pin + digit;
      setPin(next);
      if (next.length === 4) {
        setActiveField('confirm');
        setPinError(false);
      }
      return;
    }
    if (confirmPin.length >= 4) return;
    const next = confirmPin + digit;
    setConfirmPin(next);
    if (next.length === 4) {
      if (next === pin) {
        setPinError(false);
      } else {
        setPinError(true);
        setConfirmPin('');
      }
    }
  };

  const eraseDigit = () => {
    if (submitting) return;
    setSubmitError(null);
    if (activeField === 'confirm') {
      if (confirmPin.length > 0) {
        setConfirmPin(confirmPin.slice(0, -1));
        setPinError(false);
      } else {
        setActiveField('pin');
      }
      return;
    }
    setPin(pin.slice(0, -1));
    setConfirmPin('');
    setPinError(false);
  };

  const submit = async (event: React.MouseEvent<HTMLAnchorElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSubmitting(true);
    setSubmitError(null);
    try {
      await createStudent({ name: name.trim(), classNo, avatar, kidPin: pin });
      navigate('/');
    } catch (err) {
      const status = (err as { status?: number }).status;
      const message = String((err as { message?: string }).message ?? '');
      setSubmitError(
        status === 400 && /at most 3|maximum/i.test(message)
          ? 'সর্বোচ্চ ৩ জন সন্তান যোগ করা যায়'
          : 'সন্তান যোগ করা যায়নি। আবার চেষ্টা করো।',
      );
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div data-testid="onboarding-page">
      <span className="sr-only" data-testid="screen-data-status">{data ? 'synced' : 'loading'}<span className="sr-only" data-testid="session-user">{sessionUser?.email ?? ''}</span></span>
      <header className="ksr-appbar" >
          <a className="ksr-back" href="/auth/signup" aria-label="ফিরে যান" data-testid="sub-back">
            <ArrowLeft  />
            ফিরে যান
          </a>
          <span className="ksr-appbar-title" data-slot="title" data-testid="sub-title">সেটআপ</span>
        </header>
      
        <main className="ksr-main onb-body" >
      
          
          <section className="ksr-hero" data-component="card" aria-labelledby="onboarding-heading">
            <div className="media media-photo" data-component="media">
              <CoverFill icon={Rocket} size="xxl" />
            </div>
            <div className="row" style={{ marginTop: 'var(--space-lg)' }}>
              <h1 className="t-title-lg ksr-grow" id="onboarding-heading" data-testid="onboarding-heading">সেটআপ</h1>
              <p className="t-body-sm t-bold" data-testid="onboarding-step-count">১ / ৩ ধাপ</p>
            </div>
            <div className="onb-progress" style={{ marginTop: 'var(--space-md)' }}>
              <div className="progress" role="progressbar" aria-valuenow={33} aria-valuemin={0} aria-valuemax={100} aria-label="সেটআপের অগ্রগতি">
                <div className="progress-fill" style={{ width: '33%' }} data-testid="onboarding-progress-fill"></div>
              </div>
            </div>
          </section>
      
          
          <section className="ksr-section" aria-labelledby="onboarding-class-heading">
            <h2 className="ksr-hd" id="onboarding-class-heading" data-testid="onboarding-class-heading">ধাপ ১ — শিশুর নাম ও শ্রেণি</h2>
      
            
            <div className="field" style={{ marginTop: 'var(--space-md)' }}>
              <label className="label" htmlFor="onboarding-name" data-testid="onboarding-name-label">শিশুর নাম</label>
              <input className="input" type="text" id="onboarding-name" name="displayName" minLength={2} maxLength={30} autoComplete="off" placeholder="যেমন: রাফিদ হাসান" value={name} onChange={(e) => setName(e.target.value)} data-testid="onboarding-name-input" />
              <p className="help-text" data-testid="onboarding-name-help">২ থেকে ৩০ অক্ষর · এটি শুধু প্রদর্শনের নাম, পরে বদলানো যাবে</p>
            </div>
      
            <p className="label" style={{ marginTop: 'var(--space-lg)' }} data-testid="onboarding-class-question">কোন শ্রেণিতে পড়ো?</p>
            <div className="onb-classes" data-component="list" onChange={(e) => setClassNo(Number((e.target as HTMLInputElement).value))}>
              <label className="card card-interactive onb-tile">
                <input className="onb-radio" type="radio" name="onboarding-class" value="1" data-testid="onboarding-class-1" />
                <School  />
                <span className="t-body t-semibold" data-testid="onboarding-class-1-label">প্রথম শ্রেণি</span>
              </label>
              <label className="card card-interactive onb-tile">
                <input className="onb-radio" type="radio" name="onboarding-class" value="2" data-testid="onboarding-class-2" />
                <School  />
                <span className="t-body t-semibold" data-testid="onboarding-class-2-label">দ্বিতীয় শ্রেণি</span>
              </label>
              <label className="card card-interactive onb-tile">
                <input className="onb-radio" type="radio" name="onboarding-class" value="3" data-testid="onboarding-class-3" />
                <School  />
                <span className="t-body t-semibold" data-testid="onboarding-class-3-label">তৃতীয় শ্রেণি</span>
              </label>
              <label className="card card-interactive onb-tile">
                <input className="onb-radio" type="radio" name="onboarding-class" value="4" defaultChecked data-testid="onboarding-class-4" />
                <School  />
                <span className="t-body t-semibold" data-testid="onboarding-class-4-label">চতুর্থ শ্রেণি</span>
              </label>
              <label className="card card-interactive onb-tile">
                <input className="onb-radio" type="radio" name="onboarding-class" value="5" data-testid="onboarding-class-5" />
                <School  />
                <span className="t-body t-semibold" data-testid="onboarding-class-5-label">পঞ্চম শ্রেণি</span>
              </label>
            </div>
          </section>
      
          
          <section className="ksr-section" aria-labelledby="onboarding-avatar-heading">
            <h2 className="ksr-hd" id="onboarding-avatar-heading" data-testid="onboarding-avatar-heading">ধাপ ২ — অ্যাভাটার বাছুন</h2>
            <div className="onb-avatars" data-component="list" style={{ marginTop: 'var(--space-md)' }} onChange={(e) => setAvatar((e.target as HTMLInputElement).value)}>
              <label className="card card-interactive onb-avatar-tile">
                <input className="onb-avatar-radio" type="radio" name="onboarding-avatar" value="owl" defaultChecked data-testid="onboarding-avatar-1" />
                <span className="avatar avatar-xl" aria-hidden="true" data-testid="onboarding-avatar-1-mark">উ</span>
                <span className="t-caption" data-testid="onboarding-avatar-1-label">উল্লুখ</span>
              </label>
              <label className="card card-interactive onb-avatar-tile">
                <input className="onb-avatar-radio" type="radio" name="onboarding-avatar" value="star" data-testid="onboarding-avatar-2" />
                <span className="avatar avatar-xl" aria-hidden="true" data-testid="onboarding-avatar-2-mark">তা</span>
                <span className="t-caption" data-testid="onboarding-avatar-2-label">তারা</span>
              </label>
              <label className="card card-interactive onb-avatar-tile">
                <input className="onb-avatar-radio" type="radio" name="onboarding-avatar" value="flower" data-testid="onboarding-avatar-3" />
                <span className="avatar avatar-xl" aria-hidden="true" data-testid="onboarding-avatar-3-mark">ফু</span>
                <span className="t-caption" data-testid="onboarding-avatar-3-label">ফুল</span>
              </label>
              <label className="card card-interactive onb-avatar-tile">
                <input className="onb-avatar-radio" type="radio" name="onboarding-avatar" value="rocket" data-testid="onboarding-avatar-4" />
                <span className="avatar avatar-xl" aria-hidden="true" data-testid="onboarding-avatar-4-mark">র</span>
                <span className="t-caption" data-testid="onboarding-avatar-4-label">রকেট</span>
              </label>
              <label className="card card-interactive onb-avatar-tile">
                <input className="onb-avatar-radio" type="radio" name="onboarding-avatar" value="fish" data-testid="onboarding-avatar-5" />
                <span className="avatar avatar-xl" aria-hidden="true" data-testid="onboarding-avatar-5-mark">মা</span>
                <span className="t-caption" data-testid="onboarding-avatar-5-label">মাছ</span>
              </label>
              <label className="card card-interactive onb-avatar-tile">
                <input className="onb-avatar-radio" type="radio" name="onboarding-avatar" value="bird" data-testid="onboarding-avatar-6" />
                <span className="avatar avatar-xl" aria-hidden="true" data-testid="onboarding-avatar-6-mark">পা</span>
                <span className="t-caption" data-testid="onboarding-avatar-6-label">পাখি</span>
              </label>
              <label className="card card-interactive onb-avatar-tile">
                <input className="onb-avatar-radio" type="radio" name="onboarding-avatar" value="river" data-testid="onboarding-avatar-7" />
                <span className="avatar avatar-xl" aria-hidden="true" data-testid="onboarding-avatar-7-mark">ন</span>
                <span className="t-caption" data-testid="onboarding-avatar-7-label">নদী</span>
              </label>
              <label className="card card-interactive onb-avatar-tile">
                <input className="onb-avatar-radio" type="radio" name="onboarding-avatar" value="sun" data-testid="onboarding-avatar-8" />
                <span className="avatar avatar-xl" aria-hidden="true" data-testid="onboarding-avatar-8-mark">সূ</span>
                <span className="t-caption" data-testid="onboarding-avatar-8-label">সূর্য</span>
              </label>
            </div>
          </section>
      
          
          <section className="ksr-section" aria-labelledby="onboarding-pin-heading">
            <h2 className="ksr-hd" id="onboarding-pin-heading" data-testid="onboarding-pin-heading">ধাপ ৩ — চার সংখ্যার পিন দিন</h2>
            <p className="t-caption" style={{ marginTop: 'var(--space-sm)' }} data-testid="onboarding-pin-help">
              শিশু এই পিন দিয়েই লগ ইন করবে। দুইবার একই পিন দিতে হবে — কেউ জানে না।
            </p>
      
            <div className="ksr-panel onb-pin" style={{ marginTop: 'var(--space-md)' }} data-component="card">
              <div className="onb-pin-row">
                <span className="t-body-sm t-semibold" data-testid="onboarding-pin-label">পিন</span>
                <span className="onb-dots" role="img" aria-label="পিনের চারটি ঘর" data-testid="onboarding-pin-dots">
                  {Array.from({ length: 4 }, (_, i) => (
                    <span key={i} className={i < pin.length ? 'onb-dot is-filled' : 'onb-dot'} data-testid={`onboarding-pin-dot-${i + 1}`}></span>
                  ))}
                </span>
              </div>
      
              <div className="onb-pin-row">
                <span className="t-body-sm t-semibold" data-testid="onboarding-pin-confirm-label">আবার লিখুন</span>
                <span className="onb-dots" role="img" aria-label="পিন নিশ্চিত করার চারটি ঘর" data-testid="onboarding-pin-confirm-dots">
                  {Array.from({ length: 4 }, (_, i) => (
                    <span key={i} className={i < confirmPin.length ? 'onb-dot is-filled' : 'onb-dot'} data-testid={`onboarding-pin-confirm-dot-${i + 1}`}></span>
                  ))}
                </span>
              </div>
      
              <div className="onb-keypad" role="group" aria-label="বাংলা সংখ্যার কীপ্যাড" data-testid="onboarding-keypad">
                {['১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯'].map((digit, index) => (
                  <button key={digit} className="onb-key" type="button" onClick={() => pressDigit(digit)} data-testid={`onboarding-key-${index + 1}`}>{digit}</button>
                ))}
                <span aria-hidden="true"></span>
                <button className="onb-key" type="button" onClick={() => pressDigit('০')} data-testid="onboarding-key-0">০</button>
                <button className="onb-key" type="button" aria-label="শেষ সংখ্যাটি মুছুন" onClick={eraseDigit} data-testid="onboarding-key-back">
                  <Delete  />
                </button>
              </div>
      
              {pinError ? <p className="error-text" role="alert" data-testid="onboarding-pin-error">পিন দুইবার মিলতে হবে</p> : null}
              {submitError ? <p className="error-text" role="alert" data-testid="onboarding-submit-error">{submitError}</p> : null}
            </div>
          </section>
      
          
          <a className={canSubmit ? 'ksr-btn is-block' : 'ksr-btn is-block onb-off'} href="/" aria-disabled={!canSubmit} onClick={submit} data-testid="onboarding-start">
            <Rocket  />
            শুরু করো
          </a>
      
        </main>
    </div>
  );
}
